//! AI review for data-changing queries (ADR-008).
//!
//! When a connection's effective safety policy requires it, a data-changing
//! batch must carry a generated plain-language review before it may run. The
//! review is generated by the local AI runtime (the same Ollama endpoint the
//! query summaries use) and the gate FAILS CLOSED: no review, no run.
//!
//! Pure prompt/response logic lives here with unit tests; the async call is a
//! thin reqwest wrapper mirroring `query_ai_summary`. Nothing in this module
//! runs in tokenizer/intellisense paths — it is reached only from the
//! execute-time mutation gate.

use serde::{Deserialize, Serialize};

/// Where reviews are generated. Mirrors the query-summary default endpoint.
pub const DEFAULT_ENDPOINT: &str = "http://127.0.0.1:11434";

/// Hard ceiling on how long a review may take before the gate fails closed.
/// Generous enough for a cold model load, short enough that a wedged runtime
/// cannot hold the Run action hostage.
pub const REVIEW_TIMEOUT_SECS: u64 = 45;

/// The instruction the model receives. Bounded output; explanation only —
/// the WE WILL MAKE bottom line comes from the deterministic analyzer, never
/// from the model.
pub fn review_prompt(sql: &str) -> String {
    format!(
        "You are reviewing a SQL batch that is about to run against a live database. In at most 120 words of plain language, explain what data this batch will change: which tables are affected, what kind of change each statement makes, and roughly how broad the impact is (single row, filtered set, or every row). Call out anything risky, such as a missing WHERE clause. Do not suggest rewrites. Do not use markdown.\n\nSQL:\n```sql\n{sql}\n```\n"
    )
}

#[derive(Serialize)]
struct GenerateRequest {
    model: String,
    prompt: String,
    stream: bool,
    options: GenerateOptions,
}

#[derive(Serialize)]
struct GenerateOptions {
    temperature: f32,
    num_predict: u32,
}

#[derive(Deserialize)]
struct GenerateResponse {
    #[serde(default)]
    response: String,
}

/// Extract the review text from an Ollama `/api/generate` response body.
/// Empty or whitespace-only reviews are failures — the gate must not show a
/// blank explanation and call it a review.
pub fn parse_generate_response(body: &str) -> Result<String, String> {
    let parsed: GenerateResponse = serde_json::from_str(body).map_err(|e| {
        crate::localization::format(
            "ai.review.unexpected_response",
            &[("error", &e.to_string())],
        )
    })?;
    let text = parsed.response.trim().to_string();
    if text.is_empty() {
        return Err(crate::localization::text("ai.review.empty_review"));
    }
    Ok(text)
}

/// Generate a review for `sql` on the local AI runtime. `model` must be
/// non-empty; `endpoint` falls back to [`DEFAULT_ENDPOINT`] when empty.
/// Errors are user-facing text (they surface in the fail-closed status).
#[cfg(not(target_arch = "wasm32"))]
pub async fn generate_review(endpoint: &str, model: &str, sql: &str) -> Result<String, String> {
    if model.trim().is_empty() {
        return Err(crate::localization::text("ai.review.no_model_configured"));
    }
    let base = if endpoint.trim().is_empty() {
        DEFAULT_ENDPOINT
    } else {
        endpoint
    };
    let url = format!("{base}/api/generate");
    let body = serde_json::to_string(&GenerateRequest {
        model: model.to_string(),
        prompt: review_prompt(sql),
        stream: false,
        options: GenerateOptions {
            temperature: 0.2,
            num_predict: 220,
        },
    })
    .map_err(|e| e.to_string())?;

    let _ = rustls::crypto::ring::default_provider().install_default();
    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(REVIEW_TIMEOUT_SECS))
        .build()
        .map_err(|e| e.to_string())?;
    let resp = client
        .post(&url)
        .header("Content-Type", "application/json")
        .body(body)
        .send()
        .await
        .map_err(|e| {
            crate::localization::format(
                "ai.review.runtime_unreachable",
                &[("error", &e.to_string())],
            )
        })?;
    if !resp.status().is_success() {
        return Err(crate::localization::format(
            "ai.review.runtime_http_error",
            &[("status", &resp.status().to_string())],
        ));
    }
    let text = resp.text().await.map_err(|e| e.to_string())?;
    parse_generate_response(&text)
}

/// Browser preview: reviews require the local runtime, which the wasm build
/// cannot reach. The gate fails closed with this explanation.
#[cfg(target_arch = "wasm32")]
pub async fn generate_review(_endpoint: &str, _model: &str, _sql: &str) -> Result<String, String> {
    Err(
        crate::browser_preview::unavailable(&crate::localization::text(
            "ai.review.browser_unavailable",
        ))
        .to_string(),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn prompt_embeds_the_sql_and_stays_explanation_only() {
        let p = review_prompt("UPDATE t SET x = 1");
        assert!(p.contains("UPDATE t SET x = 1"), "{p}");
        assert!(p.contains("Do not suggest rewrites"), "{p}");
    }

    #[test]
    fn parse_extracts_review_text() {
        let body = r#"{"model":"m","response":"This updates every row of t.","done":true}"#;
        assert_eq!(
            parse_generate_response(body).unwrap(),
            "This updates every row of t."
        );
    }

    #[test]
    fn parse_rejects_empty_reviews_and_garbage() {
        assert!(parse_generate_response(r#"{"response":"   "}"#).is_err());
        assert!(parse_generate_response("not json").is_err());
        // A body with no response field at all is an empty review.
        assert!(parse_generate_response(r#"{"done":true}"#).is_err());
    }
}
